#include <bits/stdc++.h>
using namespace std;

const int MODULUS_X = 1000000007;
const int MODULUS_Y = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> values(n);
    for (int i = 0; i < n; ++i) {
        cin >> values[i];
    }

    vector<int> values_mod(n);
    for (int i = 0; i < n; ++i) {
        values_mod[i] = values[i] % k;
    }

    if (n == 1) {
        cout << values_mod[0] << "\n";
        return 0;
    }

    vector<int> part1(values_mod.begin(), values_mod.begin() + n / 2);
    vector<int> part2(values_mod.begin() + n / 2, values_mod.end());

    unordered_set<int> setA, setB, temp_setB;

    for (int v : part1) {
        for (int prev : setA) {
            setB.insert((prev + v) % k);
        }
        setA.insert(v);
        for (int prev : setB) {
            setA.insert(prev);
        }
        setB.clear();
    }

    for (int v : part2) {
        for (int prev : setB) {
            setB.insert((prev + v) % k);
        }
        for (int prev : setA) {
            setB.insert(prev);
        }
    }

    std::vector<int> listA(setA.begin(), setA.end());
    std::vector<int> listB(setB.begin(), setB.end());

    std::sort(listA.begin(), listA.end());
    std::sort(listB.begin(), listB.end());

    int max_res = std::max(listA.back(), listB.back());
    int answer = max_res;

    for (int s_elem : listA) {
        int target = k - 1 - s_elem;
        auto it = std::upper_bound(listB.begin(), listB.end(), target);
        if (it != listB.begin()) {
            int idx = it - listB.begin();
            int r = listB[idx - 1];
            int rt = listB.back();
            int candidate1 = (r + s_elem) % k;
            int candidate2 = (s_elem + rt) % k;
            answer = std::max({answer, candidate1, candidate2});
        }
    }

    cout << answer << "\n";

    return 0;
}
